// Dates as YYYY-MM-DD, in UTC, for every report and export.
export function isoDate(d) {
  const mm = String(d.getUTCMonth()).padStart(2, "0");
  const dd = String(d.getUTCDate()).padStart(2, "0");
  return `${d.getUTCFullYear()}-${mm}-${dd}`;
}

